interface UpdatePostInput {
  title?: string
  content?: string
}

interface Post {
  id: number
  title: string
  content: string
}

interface DatedPost extends Post {
  createdAt: string
}

interface UpdatedPost extends Post {
  updatedAt: string
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function parseUpdatePostInput(value: unknown): UpdatePostInput | null {
  if (!isRecord(value)) {
    return null
  }

  const { title, content } = value

  if (
    (title !== undefined && typeof title !== 'string') ||
    (content !== undefined && typeof content !== 'string')
  ) {
    return null
  }

  return { title, content }
}

export async function GET(
  _request: Request,
  { params }: RouteContext<'/api/posts/[id]'>
): Promise<Response> {
  const { id } = await params
  const post: DatedPost = {
    id: Number.parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post, { status: 200 })
}

export async function PUT(
  request: Request,
  { params }: RouteContext<'/api/posts/[id]'>
): Promise<Response> {
  const { id } = await params
  let payload: unknown

  try {
    payload = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const input = parseUpdatePostInput(payload)

  if (input === null) {
    return Response.json({ error: 'Invalid post data' }, { status: 400 })
  }

  const updatedPost: UpdatedPost = {
    id: Number.parseInt(id, 10),
    title: input.title || `Post ${id}`,
    content: input.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: Request,
  { params }: RouteContext<'/api/posts/[id]'>
): Promise<Response> {
  const { id } = await params

  return Response.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}
